import { ComponentProps } from 'react';

export const iconSizes = ['large', 'medium', 'small', 'tiny'] as const;

export const notificationVariants = ['default', 'brand'] as const;

type DivElementProps = ComponentProps<'div'>;

export type IconProps = React.PropsWithoutRef<
  Omit<DivElementProps, 'children'>
> & {
  size?: (typeof iconSizes)[number];
  notificationVariant?: (typeof notificationVariants)[number];
  icon: React.FunctionComponent;
};
