import React from 'react';

import { Slot } from '@radix-ui/react-slot';
import clsx from 'clsx';

import { getOptionalTextStyles, getStyles } from './Label.css';
import { LabelProps } from './Label.types';

export const Label = ({
  className,
  children,
  asChild,
  optionalText,
  error,
  ...rest
}: LabelProps) => {
  const styles = getStyles({ error });
  const optionalTextStyles = getOptionalTextStyles();
  const Component = asChild ? Slot : 'label';

  return (
    <Component className={clsx(styles, className)} {...rest}>
      <>
        {children}
        {!!optionalText && (
          <span className={clsx(optionalTextStyles)}>({optionalText})</span>
        )}
      </>
    </Component>
  );
};
