import { ComponentProps, FunctionComponent } from 'react';

export const buttonSizeOptions = ['small', 'medium', 'large'] as const;
export const buttonIconPositionOptions = ['leading', 'trailing'] as const;
export const buttonVariantOptions = [
  'primary',
  'secondary',
  'tertiary',
  'destructive',
] as const;

type Variant = (typeof buttonVariantOptions)[number];
type Size = (typeof buttonSizeOptions)[number];
type IconPosition = (typeof buttonIconPositionOptions)[number];

export type ButtonElementProps = ComponentProps<'button'>;

export type ButtonProps = React.PropsWithoutRef<ButtonElementProps> & {
  float?: boolean;
  variant?: Variant;
  disabled?: boolean;
  loading?: boolean;
  selected?: boolean;
  icon?: FunctionComponent;
  size?: Size;
  iconPosition?: IconPosition;
};
