import React from 'react';

import clsx from 'clsx';

import { getStyles } from './Dimmer.css';
import { DimmerProps } from './Dimmer.types';

export const Dimmer = ({
  className,
  intensity = 'medium',
  ...rest
}: DimmerProps) => {
  const styles = getStyles({ intensity });

  return <div className={clsx(styles, className)} {...rest} />;
};
