import React from 'react';

import { Close } from '@hexa-ui/icons';
import clsx from 'clsx';

import { Icon } from '../../Icon';
import { chipContentStyle, getIconStyle } from '../Chip.css';
import { getButtonStyle, getRemovableChipStyle } from './Removable.css';
import { RemovableChipProps, RemoveButtonProps } from './Removable.types';

export const Removable = ({
  disabled = false,
  icon,
  label,
  removeButton,
  className,
  ...rest
}: RemovableChipProps) => {
  const styles = getRemovableChipStyle({
    disabled,
    hasIcon: !!icon,
    hasRemoveButton: !!removeButton,
  });
  const removeButtonElement = removeButton
    ? React.cloneElement(removeButton, { disabled })
    : null;

  return (
    <div className={clsx(styles, className)} aria-disabled={disabled} {...rest}>
      {icon && (
        <Icon icon={icon} size="small" className={getIconStyle({ disabled })} />
      )}
      <div className={chipContentStyle}>
        {label}
        {removeButtonElement}
      </div>
    </div>
  );
};

export const RemoveButton = ({ disabled, ...rest }: RemoveButtonProps) => {
  return (
    <button
      type="button"
      className={getButtonStyle({ disabled })}
      disabled={disabled}
      {...rest}
    >
      <Icon icon={Close} size="tiny" />
    </button>
  );
};
