import { ComponentProps, FunctionComponent } from 'react';

export const textButtonSizeOptions = ['small', 'medium', 'large'] as const;
export const textButtonIconPositionOptions = ['leading', 'trailing'] as const;

type Size = (typeof textButtonSizeOptions)[number];
type IconPosition = (typeof textButtonIconPositionOptions)[number];

type ButtonElementProps = ComponentProps<'button'>;

export type TextButtonProps = ButtonElementProps & {
  icon?: FunctionComponent;
  size?: Size;
  iconPosition?: IconPosition;
};
