import React from 'react';

import clsx from 'clsx';

import { getStyles } from './Icon.css';
import { IconProps } from './Icon.types';
import { Notification } from './Notification';

export const Icon = ({
  className,
  notificationVariant,
  size = 'medium',
  icon: IconSvg,
  ...rest
}: IconProps) => {
  const styles = getStyles({ size });

  return (
    <div className={clsx(styles, className)} {...rest}>
      <IconSvg />
      {notificationVariant && (
        <Notification size={size} variant={notificationVariant} />
      )}
    </div>
  );
};
