import React from 'react';

import {
  AlertOctagon,
  AlertTriangle,
  Checkmark2,
  Close,
  Info,
} from '@hexa-ui/icons';
import clsx from 'clsx';

import { Icon } from '../Icon';
import { IconButton } from '../IconButton';
import { getIconStyles, getStyles, messageContainerStyles } from './Alert.css';
import { AlertProps } from './Alert.types';
import { AlertButton } from './AlertButton';

const mappedIcons = {
  info: Info,
  success: Checkmark2,
  warning: AlertTriangle,
  error: AlertOctagon,
};

export const Alert = ({
  className,
  children,
  variant = 'info',
  customIcon,
  actions,
  onClose,
  ...rest
}: AlertProps) => {
  const styles = getStyles({ variant });
  const iconStyles = getIconStyles({ variant });

  const icon = customIcon || mappedIcons[variant];

  return (
    <div className={clsx(styles, className)} {...rest}>
      <Icon icon={icon} size="medium" className={iconStyles} />
      <div className={messageContainerStyles}>{children}</div>
      {actions &&
        actions.map(
          (action) =>
            action && (
              <AlertButton
                key={action.label}
                variant={variant}
                action={action}
              />
            ),
        )}
      {onClose && (
        <IconButton
          icon={Close}
          variant="inherit"
          size="tiny"
          onClick={onClose}
          data-testid="alertCloseButton"
        />
      )}
    </div>
  );
};
