import React from 'react';

import { Slot } from '@radix-ui/react-slot';
import clsx from 'clsx';

import { getStyles } from './Body.css';
import { BodyProps } from './Body.types';

export const Body = ({
  children,
  className,
  variant = 'medium',
  asChild = false,
  ...rest
}: BodyProps) => {
  const Component = asChild ? Slot : 'p';
  const styles = getStyles({ variant });

  return (
    <Component className={clsx(styles, className)} {...rest}>
      {children}
    </Component>
  );
};
