import { ComponentProps } from 'react';

export const dimmerIntensityOptions = [
  'semi',
  'light',
  'medium',
  'intense',
] as const;

export type DimmerElementProps = ComponentProps<'div'>;

export type DimmerIntensityVariant = (typeof dimmerIntensityOptions)[number];

export type DimmerProps = React.PropsWithoutRef<DimmerElementProps> & {
  intensity?: DimmerIntensityVariant;
};
