import React from 'react';

import clsx from 'clsx';

import { getStyles } from './Hint.css';
import { HintProps } from './Hint.types';

export const Hint = ({ className, children, ...rest }: HintProps) => {
  const styles = getStyles();

  return (
    <span className={clsx(styles, className)} {...rest}>
      {children}
    </span>
  );
};
