import React from 'react';

import { getStyles } from './AlertButton.css';
import { AlertButtonProps } from './AlertButton.types';

export const AlertButton = ({ variant = 'info', action }: AlertButtonProps) => {
  const styles = getStyles({ variant });

  return (
    <button className={styles} type="button" onClick={action.onClick}>
      {action.label}
    </button>
  );
};
