import { ComponentProps } from 'react';

export const dropdownButtonSizeOptions = ['small', 'medium', 'large'] as const;
type Size = (typeof dropdownButtonSizeOptions)[number];

export type DropdownButtonProps = ComponentProps<'button'> & {
  size?: Size;
  icon?: React.FunctionComponent<React.SVGProps<SVGSVGElement>>;
  open?: boolean;
};
