import { ComponentProps, PropsWithoutRef } from 'react';

export const linkSizeOptions = ['small', 'medium', 'large'] as const;

export const displayOptions = ['standalone', 'inline'] as const;

export type TextLinkElementProps = ComponentProps<'a'>;

export type TextLinkProps = PropsWithoutRef<TextLinkElementProps> & {
  asChild?: boolean;
  size?: (typeof linkSizeOptions)[number];
  display?: (typeof displayOptions)[number];
};
